import{chromium}from'playwright';import fs from'fs';const b=await chromium.launch({headless:true});const p=await b.newPage({viewport:{width:390,height:844}});let errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto('http://127.0.0.1:4173/',{waitUntil:'domcontentloaded'});await p.evaluate(()=>{localStorage.setItem('lemma-entered','true');PROG.hello={done:true};PROG.abc1={done:true};PROG.abc2={done:true};PROG.abc3={done:true};PROG.rev1={done:true};uxOpen('family','family_l1')});await p.waitForTimeout(50);await p.evaluate(()=>{stage='practice';step=L.tasks.length;score=L.tasks.length;mistakes=0;WRONG=[];bestStreak=L.tasks.length;render()});await p.waitForTimeout(50);let resultWidth=await p.evaluate(()=>Math.max(document.body.scrollWidth,document.documentElement.scrollWidth));await p.screenshot({path:'artifacts/mobile-result.png',fullPage:true});await p.evaluate(()=>uxCheck('family','family_check'));let checkWidth=await p.evaluate(()=>Math.max(document.body.scrollWidth,document.documentElement.scrollWidth));await p.screenshot({path:'artifacts/mobile-check.png',fullPage:true});fs.writeFileSync('artifacts/extra.json',JSON.stringify({errors,resultWidth,checkWidth},null,2));await b.close();if(errors.length||resultWidth>390||checkWidth>390)process.exit(2);